import pandas as pd, numpy as np, statsmodels.api as sm
df=pd.read_csv('data.csv')
reg=pd.get_dummies(df.region.astype(int), prefix='reg', drop_first=True).astype(float)
def build(termsD, ldeg=3):
    X=df[['log_pre_gmv','orders','cat_share','tenure','tier']].copy()
    for k in range(1,ldeg+1): X[f'lh{k}']=df.log_hist_days**k
    X=pd.concat([X,reg],axis=1)
    for t in termsD:
        if t=='D': X['D']=df.D
        elif t=='D2': X['D2']=df.D**2
        elif t=='D3': X['D3']=df.D**3
        elif t=='logD': X['logD']=np.log(df.D)
        elif t=='D_gt16': X['D_gt16']=(df.D-16)*(df.D>16)
    return sm.add_constant(X)
models={
 'linear':['D'],
 'quad':['D','D2'],
 'cubic':['D','D2','D3'],
 'log':['logD'],
 'piece16':['D','D_gt16'],
}
for name,terms in models.items():
    X=build(terms)
    m=sm.OLS(df.dY,X).fit(cov_type='HC3')
    print(name,'R2',round(m.rsquared,4),'AIC',round(m.aic,1),'BIC',round(m.bic,1))
